def eventualSafeNodes(V, adj):
    # Create a reverse adjacency list
    rev_adj = [[] for _ in range(V)]
    in_degree = [0] * V
    for node in range(V):
        for neighbor in adj[node]:
            rev_adj[neighbor].append(node)
            in_degree[node] += 1

    # Queue for processing nodes with in_degree 0
    queue = [node for node in range(V) if in_degree[node] == 0]

    # List to store safe nodes
    safe_nodes = []

    # Process nodes with in_degree 0
    while queue:
        node = queue.pop(0)
        safe_nodes.append(node)
        for neighbor in rev_adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Return the sorted list of safe nodes
    return sorted(safe_nodes)
